//! videodec.resource's functions: the chip's video decoder, a stream fed
//! a picture at a time and its frames handed out in the order they are
//! shown (sdk/resources/videodec.zig). A resource: no Open or Close, its
//! first function in the first slot. The base comes from
//! OpenResource("videodec.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/videodec_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const videodec = @import("../resources/videodec.zig");
const utility = @import("../libs/utility/utility.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "videodec.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const VideoDecCodecs = libraries.lvo(0);
    pub const OpenVideoDecoder = libraries.lvo(1);
    pub const CloseVideoDecoder = libraries.lvo(2);
    pub const FeedVideoDecoder = libraries.lvo(3);
    pub const DecodeVideoFrame = libraries.lvo(4);
    pub const ReleaseVideoFrame = libraries.lvo(5);
    pub const GetVideoDecoderInfo = libraries.lvo(6);
    pub const FlushVideoDecoder = libraries.lvo(7);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const VideoDecCodecs = *const fn (*VideoDecBase) callconv(.c) u32;
    pub const OpenVideoDecoder = *const fn (*VideoDecBase, u32, ?[*]const utility.TagItem, ?*u32) callconv(.c) ?*videodec.VideoDecoder;
    pub const CloseVideoDecoder = *const fn (*VideoDecBase, ?*videodec.VideoDecoder) callconv(.c) void;
    pub const FeedVideoDecoder = *const fn (*VideoDecBase, *videodec.VideoDecoder, ?[*]const u8, u32, u64, u32) callconv(.c) u32;
    pub const DecodeVideoFrame = *const fn (*VideoDecBase, *videodec.VideoDecoder, *videodec.VideoDecFrame) callconv(.c) u32;
    pub const ReleaseVideoFrame = *const fn (*VideoDecBase, *videodec.VideoDecoder, *videodec.VideoDecFrame) callconv(.c) void;
    pub const GetVideoDecoderInfo = *const fn (*VideoDecBase, *videodec.VideoDecoder, *videodec.VideoDecInfo) callconv(.c) u32;
    pub const FlushVideoDecoder = *const fn (*VideoDecBase, *videodec.VideoDecoder) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const VideoDecBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *VideoDecBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The codecs the chip decodes, a VDCODEC_* bit each; 0 for none.
    pub fn VideoDecCodecs(self: *VideoDecBase) u32 {
        return libraries.call(self, LVO.VideoDecCodecs, Fn.VideoDecCodecs, .{});
    }

    /// A decoder for `codec` (a VDCODEC_*), with VDA_* tags; the first wakes
    /// the chip and loads its firmware. Null, and why in `err` (VDERR_*),
    /// when it failed. A Process: it reads the firmware's file.
    pub fn OpenVideoDecoder(self: *VideoDecBase, codec: u32, tags: ?[*]const utility.TagItem, err: ?*u32) ?*videodec.VideoDecoder {
        return libraries.call(self, LVO.OpenVideoDecoder, Fn.OpenVideoDecoder, .{ codec, tags, err });
    }

    /// The decoder closed, its frames with it - those handed out too.
    pub fn CloseVideoDecoder(self: *VideoDecBase, decoder: ?*videodec.VideoDecoder) void {
        return libraries.call(self, LVO.CloseVideoDecoder, Fn.CloseVideoDecoder, .{decoder});
    }

    /// One picture's data fed, with the time it is shown at; VDFEED_END with
    /// the last. VDERR_OK, VDERR_FULL when there is no room for it yet.
    pub fn FeedVideoDecoder(self: *VideoDecBase, decoder: *videodec.VideoDecoder, data: ?[*]const u8, length: u32, time: u64, flags: u32) u32 {
        return libraries.call(self, LVO.FeedVideoDecoder, Fn.FeedVideoDecoder, .{ decoder, data, length, time, flags });
    }

    /// The next frame in the order frames are shown, into `frame`: VDERR_OK,
    /// VDERR_NEED_DATA, VDERR_END after the last, or why not. Waits for the
    /// chip.
    pub fn DecodeVideoFrame(self: *VideoDecBase, decoder: *videodec.VideoDecoder, frame: *videodec.VideoDecFrame) u32 {
        return libraries.call(self, LVO.DecodeVideoFrame, Fn.DecodeVideoFrame, .{ decoder, frame });
    }

    /// A frame DecodeVideoFrame handed out given back to the decoder.
    pub fn ReleaseVideoFrame(self: *VideoDecBase, decoder: *videodec.VideoDecoder, frame: *videodec.VideoDecFrame) void {
        return libraries.call(self, LVO.ReleaseVideoFrame, Fn.ReleaseVideoFrame, .{ decoder, frame });
    }

    /// What the stream is, into `info`: VDERR_OK, or VDERR_NEED_DATA before
    /// the decoder has read its parameter sets.
    pub fn GetVideoDecoderInfo(self: *VideoDecBase, decoder: *videodec.VideoDecoder, info: *videodec.VideoDecInfo) u32 {
        return libraries.call(self, LVO.GetVideoDecoderInfo, Fn.GetVideoDecoderInfo, .{ decoder, info });
    }

    /// What was fed and not yet shown dropped, for a seek; the frames handed
    /// out stay the caller's.
    pub fn FlushVideoDecoder(self: *VideoDecBase, decoder: *videodec.VideoDecoder) void {
        return libraries.call(self, LVO.FlushVideoDecoder, Fn.FlushVideoDecoder, .{decoder});
    }
};
